"""Exercise TLS admission with ClientHellos generated by the local TLS stack."""

from io import BytesIO
from pathlib import Path
import runpy
import socket
import ssl
from threading import Thread
from tempfile import TemporaryDirectory
import time
import unittest
from unittest.mock import Mock


TLS = runpy.run_path(str(Path(__file__).with_name("tls-admission.py")))
FIXTURE = runpy.run_path(str(Path(__file__).with_name("tls-fixture.py")))
NAME = TLS["NAME"].decode()


def client_hello(name):
    context = ssl.create_default_context()
    context.check_hostname = False
    outgoing = ssl.MemoryBIO()
    peer = context.wrap_bio(ssl.MemoryBIO(), outgoing, server_hostname=name)
    try:
        peer.do_handshake()
    except ssl.SSLWantReadError:
        return outgoing.read()
    raise AssertionError("expected a ClientHello")


def extension(kind, value):
    return kind.to_bytes(2) + len(value).to_bytes(2) + value


class TLSAdmissionTest(unittest.TestCase):
    def read(self, wire, *, timeout=1):
        receiver, writer = socket.socketpair()
        with receiver, writer:
            writer.sendall(wire)
            return TLS["read_client_hello"](receiver, deadline=time.monotonic() + timeout)

    def test_requires_expected_sni_and_admits_split_hello_once(self):
        hello = client_hello(NAME)
        self.assertEqual(self.read(hello), hello)
        first, second = hello[5:7], hello[7:]
        split = hello[:3] + len(first).to_bytes(2) + first + hello[:3] + len(second).to_bytes(2) + second
        self.assertEqual(self.read(split), split)
        for name in (None, "other.fixture.invalid"):
            with self.subTest(name=name), self.assertRaises(TLS["Refused"]):
                self.read(client_hello(name))

    def test_refuses_duplicate_and_encrypted_server_name(self):
        name = NAME.encode()
        sni = extension(0, (len(name) + 3).to_bytes(2) + b"\x00" + len(name).to_bytes(2) + name)
        hello_prefix = bytes(34) + b"\x00\x00\x02\x13\x01\x01\x00"
        for tail in (sni, extension(0xFE0D, b"x"), extension(0xFFCE, b"x")):
            fields = sni + tail
            with self.subTest(tail=tail), self.assertRaises(TLS["Refused"]):
                TLS["require_server_name"](hello_prefix + len(fields).to_bytes(2) + fields)

    def test_refuses_wrong_record_and_bounds_wait_and_reads(self):
        with self.assertRaises(TLS["Refused"]):
            self.read(b"\x17\x03\x03\x00\x01x")
        with self.assertRaises(TLS["Refused"]):
            self.read(b"\x16\x03\x03\xff\xff")
        with self.assertRaises(TimeoutError):
            self.read(b"", timeout=.01)

    def test_rejected_hello_never_reaches_fake_peer(self):
        receiver, writer = socket.socketpair()
        listener = Mock()
        listener.accept.return_value = receiver, None
        context = Mock()
        evidence = []
        authority = NAME.encode() + b":443"
        with receiver, writer:
            # Stage CONNECT independently so the fixture will parse the TLS hello next.
            writer.sendall(b"CONNECT " + authority + b" HTTP/1.1\r\nHost: " + authority + b"\r\n\r\n")
            with writer.makefile("rb") as response:
                writer.settimeout(2)
                worker = Thread(target=FIXTURE["serve_once"], args=(listener, context, evidence))
                worker.start()
                try:
                    self.assertEqual(response.read(len(TLS["ESTABLISHED"])), TLS["ESTABLISHED"])
                    writer.sendall(client_hello("other.fixture.invalid"))
                    self.assertEqual(response.read(1), b"")
                finally:
                    writer.shutdown(socket.SHUT_RDWR)
                    worker.join(2)
            self.assertFalse(worker.is_alive())
            self.assertEqual(evidence, [])
            context.wrap_socket.assert_not_called()

    def test_premature_eof_does_not_confirm_cancellation(self):
        peer = Mock()
        peer.recv.return_value = b""
        cancellation = Mock()
        cancellation.record_eof.return_value = "premature_peer_close"
        code = b"oc-sandbox-synthetic-invalid-code"
        peer.makefile.return_value = BytesIO(b"POST /token HTTP/1.1\r\n"
                                             + f"Content-Length: {len(code)}\r\n\r\n".encode() + code)
        self.assertEqual(FIXTURE["fake_oauth"](peer, cancellation), "premature_peer_close")
        cancellation.ready.assert_called_once_with(peer)

    def test_stop_requires_open_sockets_and_precedes_eof(self):
        bridge, bridge_writer = socket.socketpair()
        peer, peer_writer = socket.socketpair()
        with bridge, bridge_writer, peer, peer_writer, TemporaryDirectory() as temp:
            observed = FIXTURE["CancellationEvidence"](Path(temp) / "ready")
            observed.bridge = bridge
            observed.ready(peer)
            observed.stop_requested()
            self.assertEqual(observed.record_eof(), "cancelled_open_peer")
            second = FIXTURE["CancellationEvidence"](Path(temp) / "second-ready")
            second.bridge = bridge
            second.ready(peer)
            bridge_writer.shutdown(socket.SHUT_WR)
            with self.assertRaises(FIXTURE["PrematureClose"]):
                second.stop_requested()
            self.assertEqual(second.record_eof(), "premature_peer_close")


if __name__ == "__main__":
    unittest.main()
